.workspace {
  position: relative;
  width: 100%;
  height: 100%;
  background: #e2e8f0;
  overflow: hidden;
}
.workspace.pour-mode {
  cursor: crosshair;
}
.scene {
  position: relative;
  width: 100%;
  height: 100%;
  background:
    repeating-linear-gradient(0deg, transparent, transparent 49px, rgba(0,0,0,0.025) 49px, rgba(0,0,0,0.025) 50px),
    repeating-linear-gradient(90deg, transparent, transparent 49px, rgba(0,0,0,0.025) 49px, rgba(0,0,0,0.025) 50px);
}
.digital-meter {
  position: absolute;
  top: 12px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 100;
  display: flex;
  gap: 1.5rem;
  background: linear-gradient(135deg, #1e293b, #334155);
  border: 2px solid #475569;
  border-radius: 0.6rem;
  padding: 0.5rem 1.2rem;
  box-shadow: 0 4px 15px rgba(0,0,0,0.25), inset 0 1px 0 rgba(255,255,255,0.1);
  font-family: 'Segoe UI', monospace;
}
.meter-row {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.15rem;
}
.meter-row.spill .meter-value {
  color: #f87171;
}
.meter-label {
  font-size: 0.6rem;
  color: #94a3b8;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.meter-value {
  font-size: 1.1rem;
  font-weight: 800;
  color: #34d399;
  text-shadow: 0 0 8px rgba(52,211,153,0.4);
}
.meter-value small {
  font-size: 0.65rem;
  font-weight: 600;
  margin-right: 0.1rem;
  color: #94a3b8;
}

